    static func staleRow(
        key: String, value: GraphicPropValue, _ binding: InspectorBinding,
        clips: @escaping () -> [ClipSnapshot]
    ) -> NSView {
        let (label, readout) = staleLabels(key: key, value: value)
        let remove = OptionButtonControl(
